char buf_fixed[1024];
char* cwd_fixed = getcwd(buf_fixed, sizeof(buf_fixed));
if (cwd_fixed == NULL) { /* Error (EACCES, ERANGE) */ }

// Dynamic Allocation (POSIX standard, size=0)
char* cwd_dyn = getcwd(NULL, 0);
if (cwd_dyn != NULL) {
    // Use cwd_dyn
    free(cwd_dyn); // Must free allocated memory
}

// GNU Variant (allocates memory internally)
char* gnu_cwd = get_current_dir_name();
if (gnu_cwd != NULL) {
    free(gnu_cwd);
}
